{project_context}

Heutiges Datum: {today}

example:
Schreibenart: behinderung
Eingabe: "Bagger ausgefallen, Baustelle steht seit Dienstag."
Ausgabe:
{
  "complete": false,
  "questions": [
    { "field": "Datum Beginn", "question": "An welchem Datum hat der Stillstand begonnen?", "example": "17.11.2026" },
    { "field": "Verursacher/Verantwortungsbereich", "question": "Warum fiel der Bagger aus – liegt die Ursache beim Auftraggeber oder bei uns?", "example": "Zufahrt vom AG gesperrt, Bagger kam nicht aufs Baufeld" },
    { "field": "voraussichtliche Auswirkung", "question": "Wie lange wird sich der Bauablauf voraussichtlich verzögern?", "example": "ca. 5 Arbeitstage" }
  ]
}

output_format:
JSON mit genau diesen Schlüsseln:
{
  "complete": boolean,
  "questions": [ { "field": string, "question": string, "example": string } ]
}
